import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import Ajv2020 from "ajv/dist/2020";
import { describe, it } from "@jest/globals";
import { buildArtifacts, ids, packetDir, writeArtifacts } from "../../../scripts/preverif/generate-rc5-maya-independent-review-batch4";

const sha = (v: string) => crypto.createHash("sha256").update(v).digest("hex");
const reviewedBlockers = [
  "The no-overlap rule requires project-level confirmation of boundary exclusivity. The PDD provides boundary coordinates and references supporting files (KML, shapefiles) that are absent from the frozen packet. Without these, the boundary cannot be independently confirmed as non-overlapping.",
  "External-program double-counting prevention (2.5.13.1-2) is documented, but the rule requires both external and internal exclusion tracking. The frozen packet does not contain evidence of intra-project exclusion tracking.",
  "The proxy similarity analysis is documented in the PDD but the underlying RRD justification and LIC source data (Appendix XYZ) are absent, preventing full verification of the reference region delineation.",
  "The PDD combines two forest types into one stratum due to remote sensing limitations but does not demonstrate that the combined types have materially similar carbon stocks. The stratification requirement may not be satisfied by a limitation-based justification alone.",
  "Pool inclusion/exclusion is described and symmetric accounting is confirmed, but the supporting appendices (21, 22) and methodology pool crosswalk are absent, preventing full verification against the methodology requirements.",
  "The 2012-2021 historical analysis window is described but not explicitly identified as the fixed baseline-modeling period required by the methodology. The relationship between the historical analysis window and the fixed baseline-modeling period is unclear from the evidence.",
  "VT0001 applicability and Steps 1-2 are documented, but Step 3 (Barrier Analysis) is absent, preventing confirmation that the VT0001 additionality analysis is complete.",
];
describe("RC5-2 Maya independent review batch 4", () => {
  it("derives exactly seven current non-Batch-3 provisional rules", () => { const { packet } = buildArtifacts(); assert.equal(packet.frozenInventory.reviewed, 45); assert.equal(packet.frozenInventory.provisional, 13); assert.deepEqual(packet.selectedRuleIds, ids); assert.equal(packet.rules.length, 7); });
  it("freezes machine-only summaries without reviewed-truth judgments", () => { const { packet } = buildArtifacts(); const packetJson = JSON.stringify(packet); for (const rule of packet.rules as any[]) { assert.deepEqual(Object.keys(rule.machineProposalSummary).sort(), ["applicability", "evidenceState", "outcome"]); assert.deepEqual(rule.machineProposalSummary, { evidenceState: rule.frozenMachineRow.proposedEvidenceStatus, applicability: rule.frozenMachineRow.proposedApplicability, outcome: rule.frozenMachineRow.upstreamStatus }); assert.equal("currentProvisionalJudgment" in rule, false); assert.equal("provisionalReason" in rule, false); assert.equal(rule.frozenMachineRowSha256, sha(JSON.stringify(rule.frozenMachineRow))); assert.ok(rule.existingAcceptedEvidence); assert.ok(rule.existingRejectedEvidence); assert.ok(rule.methodologyContract.contractTextSha256); assert.ok(rule.candidateEvidence.length >= 2); for (const e of rule.candidateEvidence) { assert.equal(e.quote, packet.contexts[e.contextId].exactQuote); assert.equal(e.documentSha256, packet.sourceDocument.contentSha256); } } for (const blocker of reviewedBlockers) assert.equal(packetJson.includes(blocker), false); assert.equal(packetJson.includes("reviewed-truth.json"), false); });
  it("keeps the response blank and regeneration deterministic", () => { const a = buildArtifacts(); const temp = fs.mkdtempSync(path.join(os.tmpdir(), "rc5-maya-batch4-")); try { writeArtifacts(temp); for (const file of ["review-packet.json", "review-response-schema.json", "review-template.json", "manifest.json"]) assert.equal(fs.readFileSync(path.join(temp, file), "utf8"), fs.readFileSync(path.join(packetDir, file), "utf8"), file); } finally { fs.rmSync(temp, { recursive: true, force: true }); } const validate = new Ajv2020({ strict: false }).compile(a.schema); assert.equal(validate(a.template), true, JSON.stringify(validate.errors)); assert.ok(a.template.decisions.every((d: any) => d.acceptedEvidence.length === 0 && d.rejectedEvidence.length === 0)); const mutated = JSON.parse(JSON.stringify(a.packet)); mutated.rules[0].frozenMachineRow.stableRuleId = "invented"; assert.notEqual(mutated.rules[0].frozenMachineRowSha256, sha(JSON.stringify(mutated.rules[0].frozenMachineRow))); });
});
